"""CENOP: turning angle generated by the CRW (pm._pres_angle) vs heading change vs realized
movement turn, days 1-5, v3.2 landscape. Locates where the reversals arise.

Usage: crw_generated_vs_realized.py <cenop data_dir with Kattegat/>
"""

import sys
from pathlib import Path

import numpy as np

REPO = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(REPO / "src"))
from cenop.core.simulation import Simulation  # noqa: E402
from cenop.landscape.cell_data import CellData  # noqa: E402
from cenop.parameters.simulation_params import SimulationParameters  # noqa: E402

params = SimulationParameters(porpoise_count=2000, sim_years=1, random_seed=42, landscape="Kattegat",
                              ships_enabled=False, turbines="off")
print({k: getattr(params, k) for k in ("corr_angle_base", "corr_angle_bathy", "corr_angle_salinity",
                                       "corr_angle_base_sd", "r2_mean", "r2_sd", "m", "inertia_const")})
cd = CellData("Kattegat", sys.argv[1])
cd.load()
sim = Simulation(params=params, cell_data=cd, seed=42)
sim.initialize()
pm = sim.population_manager


def wrap(a):
    return (a + 180.0) % 360.0 - 180.0


gen, dhead, realized = [], [], []
prev_x = prev_y = prev_dir = prev_head = None
for tick in range(1, 5 * 48 + 1):
    x0, y0, h0 = pm.x.copy(), pm.y.copy(), pm.heading.copy()
    sim.step()
    a = pm.active_mask.copy()
    move_dir = np.degrees(np.arctan2(pm.x - x0, pm.y - y0))  # compass: 0 = north, clockwise
    if tick > 48 and prev_dir is not None:
        gen.append(np.abs(pm._pres_angle[a]))
        dhead.append(np.abs(wrap(pm.heading[a] - h0[a])))
        realized.append(np.abs(wrap(move_dir[a] - prev_dir[a])))
    prev_dir = move_dir


def q(v):
    v = np.concatenate(v)
    return f"median {np.median(v):6.1f}  mean {v.mean():6.1f}  >120: {np.mean(v > 120):.3f}"


print("generated |pres_angle| :", q(gen))
print("|heading change|       :", q(dhead))
print("|realized move turn|   :", q(realized))
print("heading vs move direction offset (median |wrap(heading - move_dir)|):",
      f"{np.median(np.abs(wrap(pm.heading[pm.active_mask] - prev_dir[pm.active_mask]))):.1f}")
